import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 26 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(26)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:26]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time
from scipy.optimize import minimize

N = 26

def _pack_from_centers(centers, r0=0.05):
    # build initial array with radii, ensure inside
    arr = np.zeros((N, 3))
    for i, (x, y) in enumerate(centers):
        r = min(r0, x, 1 - x, y, 1 - y)
        arr[i] = (x, y, max(r, 1e-4))
    return arr

def _split_cell(cell_ij, k=5):
    # 5x5 grid, split cell (i,j) into 2 circles
    pts = []
    for j in range(k):
        for i in range(k):
            if (i, j) == cell_ij:
                continue
            pts.append(((i + 0.5) / k, (j + 0.5) / k))
    i, j = cell_ij
    cx, cy = (i + 0.5) / k, (j + 0.5) / k
    d = 0.5 / k * 0.5
    pts.append((cx - d, cy))
    pts.append((cx + d, cy))
    return pts[:N]

def _hex_construction():
    pts = []
    rows = 6
    for j in range(rows):
        y = (j + 0.5) / rows
        off = 0.5 / 5 if j % 2 else 0.0
        cols = 5 if j % 2 else 4
        for i in range(cols):
            x = (i + 0.5 + off) / 5
            if 0 < x < 1:
                pts.append((x, y))
    return pts[:N]

def _grid_split_center():
    return _split_cell((2, 2))

def _grid_removed_random():
    k = 5
    pts = []
    for j in range(k):
        for i in range(k):
            if (i, j) == (2, 2):
                continue
            pts.append(((i + 0.5) / k, (j + 0.5) / k))
    # two random 0.05 circles in that cell
    rng = np.random.default_rng(12345)
    cx, cy = (2 + 0.5) / k, (2 + 0.5) / k
    for _ in range(2):
        ang = rng.uniform(0, 2 * np.pi)
        rr = 0.05
        pts.append((cx + rr * np.cos(ang), cy + rr * np.sin(ang)))
    return pts[:N]

def _perturbed_split():
    base = _split_cell((0, 0))
    rng = np.random.default_rng(999)
    out = []
    for (x, y) in base:
        out.append((x + rng.uniform(-0.005, 0.005),
                    y + rng.uniform(-0.005, 0.005)))
    return out

def _unpack(z):
    return z[:N], z[N:2*N], z[2*N:]

def _objective(z):
    _, _, r = _unpack(z)
    return -np.sum(r)

def _constraints(z):
    x, y, r = _unpack(z)
    cons = []
    # inside square
    cons.append(x - r)      # >= 0
    cons.append(1 - x - r)  # >= 0
    cons.append(y - r)
    cons.append(1 - y - r)
    # pairwise: dist^2 - (ri+rj)^2 >= 0
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]
            dy = y[i] - y[j]
            cons.append(dx*dx + dy*dy - (r[i] + r[j])**2)
    return np.array(cons)

def _run_slsqp(arr, maxiter=300):
    x = arr[:, 0].copy()
    y = arr[:, 1].copy()
    r = arr[:, 2].copy()
    z0 = np.concatenate([x, y, r])
    bounds = [(0, 1)] * (2 * N) + [(1e-6, 0.5)] * N
    try:
        res = minimize(_objective, z0, method='SLSQP',
                       constraints={'type': 'ineq', 'fun': _constraints},
                       bounds=bounds,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
        z = res.x
    except Exception:
        return None
    x, y, r = _unpack(z)
    return np.column_stack([x, y, r])

def _feasible(arr, tol=0.0):
    x, y, r = arr[:, 0], arr[:, 1], arr[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    for i in range(N):
        for j in range(i + 1, N):
            dx = x[i] - x[j]
            dy = y[i] - y[j]
            if dx*dx + dy*dy < (r[i] + r[j])**2 - tol:
                return False
    return True

def _shrink(arr, eps=1e-9):
    out = arr.copy()
    out[:, 2] = np.maximum(out[:, 2] - eps, 1e-12)
    return out

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    starts = []
    starts.append(_pack_from_centers(_split_cell((0, 0))))
    starts.append(_pack_from_centers(_split_cell((4, 4))))
    starts.append(_pack_from_centers(_grid_split_center()))
    starts.append(_pack_from_centers(_hex_construction()))
    starts.append(_pack_from_centers(_grid_removed_random()))
    starts.append(_pack_from_centers(_perturbed_split()))

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (N, 3):
            starts.append(s.copy())

    best = None
    best_score = -1.0

    # also consider start directly
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (N, 3) and _feasible(s):
            sc = np.sum(s[:, 2])
            if sc > best_score:
                best_score = sc
                best = s.copy()

    n = len(starts)
    for idx, arr in enumerate(starts):
        if time.process_time() > deadline:
            break
        remaining = n - idx
        # rough per-run maxiter scaling
        res = _run_slsqp(arr, maxiter=300)
        if res is None:
            continue
        if _feasible(res):
            sc = np.sum(res[:, 2])
            if sc > best_score:
                best_score = sc
                best = res.copy()

    if best is None:
        # fallback
        best = _pack_from_centers(_split_cell((0, 0)))
        if start is not None:
            s = np.asarray(start, dtype=float)
            if s.shape == (N, 3) and _feasible(s):
                best = s.copy()

    return _shrink(best)

import numpy as np
import time
from scipy.optimize import minimize


def _split_cell_init(n=26):
    cells = [(0.0, 0.0, 1.0, 1.0)]
    while len(cells) < n:
        idx = max(range(len(cells)), key=lambda i: cells[i][2] * cells[i][3])
        x, y, w, h = cells.pop(idx)
        if w >= h:
            cells.append((x, y, w / 2, h))
            cells.append((x + w / 2, y, w / 2, h))
        else:
            cells.append((x, y, w, h / 2))
            cells.append((x, y + h / 2, w, h / 2))
    pts = []
    for (x, y, w, h) in cells[:n]:
        pts.append([x + w / 2, y + h / 2, 0.5 * min(w, h)])
    return np.array(pts)


def _feasible_shrink(arr):
    arr = arr.copy()
    n = len(arr)
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1 - r)
    for _ in range(300):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s - 1e-12:
                    excess = s - d
                    arr[i, 2] -= excess / 2 + 1e-12
                    arr[j, 2] -= excess / 2 + 1e-12
                    arr[i, 2] = max(arr[i, 2], 1e-6)
                    arr[j, 2] = max(arr[j, 2], 1e-6)
                    changed = True
        if not changed:
            break
    return arr


def _make_cons(n, eq_pairs, eq_walls):
    def wall_constraints(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def pair_constraints(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        out = []
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                out.append(dx * dx + dy * dy - (r[i] + r[j]) ** 2)
        return np.array(out)

    def eq_pair_fun(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        out = []
        for (i, j) in eq_pairs:
            dx = x[i] - x[j]; dy = y[i] - y[j]
            out.append(dx * dx + dy * dy - (r[i] + r[j]) ** 2)
        return np.array(out) if out else np.zeros(0)

    def eq_wall_fun(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        out = []
        for (i, side) in eq_walls:
            if side == 0:
                out.append(x[i] - r[i])
            elif side == 1:
                out.append(1 - x[i] - r[i])
            elif side == 2:
                out.append(y[i] - r[i])
            else:
                out.append(1 - y[i] - r[i])
        return np.array(out) if out else np.zeros(0)

    cons = [
        {'type': 'ineq', 'fun': wall_constraints},
        {'type': 'ineq', 'fun': pair_constraints},
    ]
    if eq_pairs:
        cons.append({'type': 'eq', 'fun': eq_pair_fun})
    if eq_walls:
        cons.append({'type': 'eq', 'fun': eq_wall_fun})
    return cons


def _detect_contacts(arr, thresh):
    n = len(arr)
    x = arr[:, 0]; y = arr[:, 1]; r = arr[:, 2]
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            gap = d - (r[i] + r[j])
            if gap < thresh:
                pairs.append((i, j))
    walls = []
    for i in range(n):
        if x[i] - r[i] < thresh:
            walls.append((i, 0))
        if 1 - x[i] - r[i] < thresh:
            walls.append((i, 1))
        if y[i] - r[i] < thresh:
            walls.append((i, 2))
        if 1 - y[i] - r[i] < thresh:
            walls.append((i, 3))
    return pairs, walls


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26

    if start is not None:
        init = np.asarray(start, dtype=float).copy()
    else:
        init = _split_cell_init(n)
    init = _feasible_shrink(init)

    best = init.copy()
    best_score = np.sum(best[:, 2])

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))

    def objective(v):
        return -np.sum(v.reshape(n, 3)[:, 2])

    def grad_obj(v):
        g = np.zeros_like(v)
        g.reshape(n, 3)[:, 2] = -1.0
        return g

    def try_opt(x0, cons, maxiter=800):
        try:
            res = minimize(objective, x0, jac=grad_obj, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': 1e-11})
            cand = _feasible_shrink(res.x.reshape(n, 3))
            return cand, np.sum(cand[:, 2])
        except Exception:
            return None, -1.0

    # Phase 1: equality-constrained optimization on detected contacts
    for thresh in (1e-3, 1e-2):
        if time.process_time() - t0 > budget_seconds * 0.75:
            break
        eq_pairs, eq_walls = _detect_contacts(best, thresh)
        cons = _make_cons(n, eq_pairs, eq_walls)
        cand, sc = try_opt(best.flatten(), cons)
        if cand is not None and sc > best_score + 1e-9:
            best = cand
            best_score = sc

    # Phase 2: fallback to base constraints (inequality only)
    if time.process_time() - t0 < budget_seconds * 0.85:
        cons = _make_cons(n, [], [])
        cand, sc = try_opt(best.flatten(), cons)
        if cand is not None and sc > best_score + 1e-9:
            best = cand
            best_score = sc

    # Final safety shrink
    best[:, 2] = np.maximum(best[:, 2] - 1e-9, 1e-7)
    best = _feasible_shrink(best)
    best[:, 2] = np.maximum(best[:, 2] - 1e-10, 1e-7)

    return best

import numpy as np
import time
from scipy.optimize import minimize, NonlinearConstraint


def _split_cell_init(n=26):
    cells = [(0.0, 0.0, 1.0, 1.0)]
    while len(cells) < n:
        idx = max(range(len(cells)), key=lambda i: cells[i][2] * cells[i][3])
        x, y, w, h = cells.pop(idx)
        if w >= h:
            cells.append((x, y, w / 2, h))
            cells.append((x + w / 2, y, w / 2, h))
        else:
            cells.append((x, y, w, h / 2))
            cells.append((x, y + h / 2, w, h / 2))
    pts = []
    for (x, y, w, h) in cells[:n]:
        pts.append([x + w / 2, y + h / 2, 0.5 * min(w, h)])
    return np.array(pts)


def _feasible_shrink(arr):
    arr = arr.copy()
    n = len(arr)
    for i in range(n):
        r = arr[i, 2]
        arr[i, 0] = min(max(arr[i, 0], r), 1 - r)
        arr[i, 1] = min(max(arr[i, 1], r), 1 - r)
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = arr[i, 0] - arr[j, 0]
                dy = arr[i, 1] - arr[j, 1]
                d = np.hypot(dx, dy)
                s = arr[i, 2] + arr[j, 2]
                if d < s - 1e-12:
                    excess = s - d
                    arr[i, 2] -= excess / 2 + 1e-12
                    arr[j, 2] -= excess / 2 + 1e-12
                    arr[i, 2] = max(arr[i, 2], 1e-6)
                    arr[j, 2] = max(arr[j, 2], 1e-6)
                    changed = True
        if not changed:
            break
    return arr


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26

    if start is not None:
        init = np.asarray(start, dtype=float).copy()
    else:
        init = _split_cell_init(n)

    init = _feasible_shrink(init)
    x0 = init.flatten()

    def unpack(v):
        return v.reshape(n, 3)

    def objective(v):
        return -np.sum(v.reshape(n, 3)[:, 2])

    def grad_obj(v):
        g = np.zeros_like(v)
        g.reshape(n, 3)[:, 2] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))

    def wall_constraints(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def pair_constraints(v):
        a = v.reshape(n, 3)
        x = a[:, 0]; y = a[:, 1]; r = a[:, 2]
        out = []
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                out.append(dx * dx + dy * dy - (r[i] + r[j]) ** 2)
        return np.array(out)

    cons = [
        NonlinearConstraint(wall_constraints, 0.0, np.inf),
        NonlinearConstraint(pair_constraints, 0.0, np.inf),
    ]

    best = init.copy()
    best_score = np.sum(best[:, 2])

    def run_trust(x_start):
        try:
            res = minimize(objective, x_start, jac=grad_obj, method='trust-constr',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': 2000, 'gtol': 1e-10, 'xtol': 1e-12})
            cand = _feasible_shrink(unpack(res.x))
            return cand, np.sum(cand[:, 2])
        except Exception:
            return None, -np.inf

    # First attempt from the given start
    cand, sc = run_trust(x0)
    if cand is not None and sc > best_score:
        best = cand
        best_score = sc

    # 8 perturbed restarts within time budget
    rng = np.random.default_rng(12345)
    attempt = 0
    while attempt < 8 and time.process_time() - t0 < budget_seconds * 0.85:
        attempt += 1
        pert = best.copy()
        pert[:, 0] += rng.normal(0, 0.01, n)
        pert[:, 1] += rng.normal(0, 0.01, n)
        pert = _feasible_shrink(pert)
        cand, sc = run_trust(pert.flatten())
        if cand is not None and sc > best_score:
            best = cand
            best_score = sc

    # final safety shrink
    best[:, 2] = np.maximum(best[:, 2] - 1e-9, 1e-7)
    best = _feasible_shrink(best)
    best[:, 2] = np.maximum(best[:, 2] - 1e-10, 1e-7)

    return best

import numpy as np
import time
from scipy.optimize import minimize


def _feasible_shrink(P, r, n):
    """Make (P, r) strictly feasible with a small margin."""
    r = np.maximum(r - 1e-9, 1e-12)
    for i in range(n):
        P[i, 0] = min(max(P[i, 0], r[i]), 1.0 - r[i])
        P[i, 1] = min(max(P[i, 1], r[i]), 1.0 - r[i])
    for _ in range(200):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = P[i, 0] - P[j, 0]
                dy = P[i, 1] - P[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if d < s:
                    bad = True
                    excess = (s - d) * 0.5 + 1e-12
                    r[i] = max(r[i] - excess, 1e-12)
                    r[j] = max(r[j] - excess, 1e-12)
        if not bad:
            break
    for i in range(n):
        P[i, 0] = min(max(P[i, 0], r[i]), 1.0 - r[i])
        P[i, 1] = min(max(P[i, 1], r[i]), 1.0 - r[i])
    return P, r


def _slsqp_polish(P, r, n, eq_pairs=None, eq_walls=None, maxiter=300):
    """SLSQP maximizing sum of radii with fixed topology (centres free).
    Optionally adds equality constraints for near-contacts."""
    x0 = np.concatenate([P[:, 0], P[:, 1], r])

    def obj(x):
        return -np.sum(x[2 * n:3 * n])

    def grad(x):
        g = np.zeros(3 * n)
        g[2 * n:3 * n] = -1.0
        return g

    cons = []

    for i in range(n):
        def c1(x, i=i):
            return x[i] - x[2 * n + i]
        def c2(x, i=i):
            return 1.0 - x[i] - x[2 * n + i]
        def c3(x, i=i):
            return x[n + i] - x[2 * n + i]
        def c4(x, i=i):
            return 1.0 - x[n + i] - x[2 * n + i]
        cons.append({'type': 'ineq', 'fun': c1})
        cons.append({'type': 'ineq', 'fun': c2})
        cons.append({'type': 'ineq', 'fun': c3})
        cons.append({'type': 'ineq', 'fun': c4})

    for i in range(n):
        for j in range(i + 1, n):
            def cp(x, i=i, j=j):
                dx = x[i] - x[j]
                dy = x[n + i] - x[n + j]
                s = x[2 * n + i] + x[2 * n + j]
                return dx * dx + dy * dy - s * s
            cons.append({'type': 'ineq', 'fun': cp})

    # Add equality constraints for near-contacts
    if eq_pairs:
        for (i, j) in eq_pairs:
            def ceq(x, i=i, j=j):
                dx = x[i] - x[j]
                dy = x[n + i] - x[n + j]
                s = x[2 * n + i] + x[2 * n + j]
                return dx * dx + dy * dy - s * s
            cons.append({'type': 'eq', 'fun': ceq})

    if eq_walls:
        for (i, side) in eq_walls:
            if side == 0:
                def cw(x, i=i):
                    return x[i] - x[2 * n + i]
            elif side == 1:
                def cw(x, i=i):
                    return 1.0 - x[i] - x[2 * n + i]
            elif side == 2:
                def cw(x, i=i):
                    return x[n + i] - x[2 * n + i]
            else:
                def cw(x, i=i):
                    return 1.0 - x[n + i] - x[2 * n + i]
            cons.append({'type': 'eq', 'fun': cw})

    bounds = [(0.0, 1.0)] * (2 * n) + [(1e-6, 0.5)] * n

    try:
        res = minimize(obj, x0, jac=grad, method='SLSQP', bounds=bounds,
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
        x = res.x
        if not np.all(np.isfinite(x)):
            return P, r, False
    except Exception:
        return P, r, False

    Pn = np.column_stack([x[0:n], x[n:2 * n]])
    rn = x[2 * n:3 * n].copy()
    return Pn, rn, True


def _find_contacts(P, r, n, thr):
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(P[i, 0] - P[j, 0], P[i, 1] - P[j, 1])
            if d - (r[i] + r[j]) < thr:
                pairs.append((i, j))
    walls = []
    for i in range(n):
        if P[i, 0] - r[i] < thr:
            walls.append((i, 0))
        if 1.0 - P[i, 0] - r[i] < thr:
            walls.append((i, 1))
        if P[i, 1] - r[i] < thr:
            walls.append((i, 2))
        if 1.0 - P[i, 1] - r[i] < thr:
            walls.append((i, 3))
    return pairs, walls


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    rng = np.random.default_rng(987654321)

    if start is not None:
        S = np.asarray(start, dtype=float)
        if S.shape == (n, 3):
            P = S[:, :2].copy()
            r = S[:, 2].copy()
        else:
            P = rng.uniform(0.1, 0.9, (n, 2))
            r = np.full(n, 0.01)
    else:
        pts = []
        k = 5
        for j in range(k):
            for i in range(k):
                pts.append(((i + 0.5) / k, (j + 0.5) / k))
        pts = pts[:25]
        pts.append((0.5, 0.5))
        P = np.array(pts, dtype=float)
        r = np.full(n, 0.001)

    P, r = _feasible_shrink(P, r, n)

    best_P, best_r = P.copy(), r.copy()
    best_score = r.sum()

    # First polish (free)
    Pn, rn, ok = _slsqp_polish(P, r, n)
    if ok:
        Pn, rn = _feasible_shrink(Pn, rn, n)
        if rn.sum() > best_score:
            best_P, best_r = Pn.copy(), rn.copy()
            best_score = rn.sum()

    # Equality-constrained polish with increasing thresholds
    deadline = budget_seconds * 0.93
    for thr in (5e-5, 1e-4, 1e-3):
        if time.process_time() - t0 > deadline:
            break
        pairs, walls = _find_contacts(best_P, best_r, n, thr)
        if not pairs and not walls:
            continue
        Pn, rn, ok = _slsqp_polish(best_P, best_r, n,
                                    eq_pairs=pairs, eq_walls=walls,
                                    maxiter=400)
        if ok:
            Pn, rn = _feasible_shrink(Pn, rn, n)
            if rn.sum() > best_score:
                best_P, best_r = Pn.copy(), rn.copy()
                best_score = rn.sum()

    # Perturbed restarts (free polish) with remaining time
    attempt = 0
    while time.process_time() - t0 < deadline:
        attempt += 1
        sigma = rng.uniform(0.01, 0.04)
        Pp = best_P + rng.normal(0, sigma, best_P.shape)
        Pp = np.clip(Pp, 0.0, 1.0)
        rp = best_r * rng.uniform(0.97, 1.0, n)
        Pp, rp = _feasible_shrink(Pp, rp, n)
        Pn, rn, ok = _slsqp_polish(Pp, rp, n)
        if ok:
            Pn, rn = _feasible_shrink(Pn, rn, n)
            if rn.sum() > best_score:
                best_P, best_r = Pn.copy(), rn.copy()
                best_score = rn.sum()
        if time.process_time() - t0 > deadline:
            break

    P, r = best_P, best_r
    P, r = _feasible_shrink(P, r, n)

    out = np.column_stack([P, r])
    return out

import numpy as np
import time
from scipy.optimize import minimize, least_squares


def _feasible_shrink(P, r, n, margin=1e-10):
    r = np.maximum(r - margin, 1e-12)
    for i in range(n):
        P[i, 0] = min(max(P[i, 0], r[i]), 1.0 - r[i])
        P[i, 1] = min(max(P[i, 1], r[i]), 1.0 - r[i])
    for _ in range(200):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = P[i, 0] - P[j, 0]
                dy = P[i, 1] - P[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if d < s:
                    bad = True
                    excess = (s - d) * 0.5 + 1e-12
                    r[i] = max(r[i] - excess, 1e-12)
                    r[j] = max(r[j] - excess, 1e-12)
        if not bad:
            break
    for i in range(n):
        P[i, 0] = min(max(P[i, 0], r[i]), 1.0 - r[i])
        P[i, 1] = min(max(P[i, 1], r[i]), 1.0 - r[i])
    return P, r


def _slsqp_polish(P, r, n):
    x0 = np.concatenate([P[:, 0], P[:, 1], r])

    def obj(x):
        return -np.sum(x[2 * n:3 * n])

    def grad(x):
        g = np.zeros(3 * n)
        g[2 * n:3 * n] = -1.0
        return g

    cons = []
    for i in range(n):
        def c1(x, i=i):
            return x[i] - x[2 * n + i]
        def j1(x, i=i):
            g = np.zeros(3 * n); g[i] = 1.0; g[2 * n + i] = -1.0; return g
        def c2(x, i=i):
            return 1.0 - x[i] - x[2 * n + i]
        def j2(x, i=i):
            g = np.zeros(3 * n); g[i] = -1.0; g[2 * n + i] = -1.0; return g
        def c3(x, i=i):
            return x[n + i] - x[2 * n + i]
        def j3(x, i=i):
            g = np.zeros(3 * n); g[n + i] = 1.0; g[2 * n + i] = -1.0; return g
        def c4(x, i=i):
            return 1.0 - x[n + i] - x[2 * n + i]
        def j4(x, i=i):
            g = np.zeros(3 * n); g[n + i] = -1.0; g[2 * n + i] = -1.0; return g
        cons.append({'type': 'ineq', 'fun': c1, 'jac': j1})
        cons.append({'type': 'ineq', 'fun': c2, 'jac': j2})
        cons.append({'type': 'ineq', 'fun': c3, 'jac': j3})
        cons.append({'type': 'ineq', 'fun': c4, 'jac': j4})

    for i in range(n):
        for j in range(i + 1, n):
            def cp(x, i=i, j=j):
                dx = x[i] - x[j]
                dy = x[n + i] - x[n + j]
                s = x[2 * n + i] + x[2 * n + j]
                return dx * dx + dy * dy - s * s
            def jp(x, i=i, j=j):
                g = np.zeros(3 * n)
                dx = x[i] - x[j]
                dy = x[n + i] - x[n + j]
                s = x[2 * n + i] + x[2 * n + j]
                g[i] = 2.0 * dx
                g[j] = -2.0 * dx
                g[n + i] = 2.0 * dy
                g[n + j] = -2.0 * dy
                g[2 * n + i] = -2.0 * s
                g[2 * n + j] = -2.0 * s
                return g
            cons.append({'type': 'ineq', 'fun': cp, 'jac': jp})

    bounds = [(0.0, 1.0)] * (2 * n) + [(1e-6, 0.5)] * n

    try:
        res = minimize(obj, x0, jac=grad, method='SLSQP', bounds=bounds,
                       constraints=cons,
                       options={'maxiter': 1500, 'ftol': 1e-14})
        x = res.x
    except Exception:
        return P, r

    Pn = np.column_stack([x[0:n], x[n:2 * n]])
    rn = x[2 * n:3 * n].copy()
    return Pn, rn


def _kkt_solve(P, r, n, tol=1e-7):
    active_pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(P[i, 0] - P[j, 0], P[i, 1] - P[j, 1])
            if d - (r[i] + r[j]) < tol:
                active_pairs.append((i, j))
    active_walls = []
    for i in range(n):
        if P[i, 0] - r[i] < tol:
            active_walls.append((i, 0, -1))
        if 1.0 - P[i, 0] - r[i] < tol:
            active_walls.append((i, 0, 1))
        if P[i, 1] - r[i] < tol:
            active_walls.append((i, 1, -1))
        if 1.0 - P[i, 1] - r[i] < tol:
            active_walls.append((i, 1, 1))

    na = len(active_pairs) + len(active_walls)

    def unpack(v):
        x = v[0:n]; y = v[n:2*n]; rr = v[2*n:3*n]; lam = v[3*n:3*n+na]
        return x, y, rr, lam

    def resid(v):
        x, y, rr, lam = unpack(v)
        out = []
        for (i, j) in active_pairs:
            dx = x[i] - x[j]; dy = y[i] - y[j]
            s = rr[i] + rr[j]
            out.append(dx*dx + dy*dy - s*s)
        for (i, ax, side) in active_walls:
            if ax == 0:
                out.append(x[i] - side * rr[i] if side == -1 else 1.0 - x[i] - rr[i])
            else:
                out.append(y[i] - side * rr[i] if side == -1 else 1.0 - y[i] - rr[i])
        gx = np.zeros(n); gy = np.zeros(n); gr = -np.ones(n)
        k = 0
        for (i, j) in active_pairs:
            dx = x[i] - x[j]; dy = y[i] - y[j]
            s = rr[i] + rr[j]
            L = lam[k]
            gx[i] += L * 2.0 * dx; gx[j] -= L * 2.0 * dx
            gy[i] += L * 2.0 * dy; gy[j] -= L * 2.0 * dy
            gr[i] += L * (-2.0 * s); gr[j] += L * (-2.0 * s)
            k += 1
        for (i, ax, side) in active_walls:
            L = lam[k]
            if ax == 0:
                if side == -1:
                    gx[i] += L * 1.0; gr[i] += L * (-1.0)
                else:
                    gx[i] += L * (-1.0); gr[i] += L * (-1.0)
            else:
                if side == -1:
                    gy[i] += L * 1.0; gr[i] += L * (-1.0)
                else:
                    gy[i] += L * (-1.0); gr[i] += L * (-1.0)
            k += 1
        out.extend(gx.tolist())
        out.extend(gy.tolist())
        out.extend(gr.tolist())
        return np.array(out)

    v0 = np.concatenate([P[:, 0], P[:, 1], r, np.full(na, 0.01)])
    try:
        res = least_squares(resid, v0, method='lm', max_nfev=5000,
                            xtol=1e-15, ftol=1e-15, gtol=1e-15)
        v = res.x
    except Exception:
        return P, r
    x, y, rr, lam = unpack(v)
    Pn = np.column_stack([x, y])
    return Pn, rr.copy()


def _energy(P, r, n):
    E = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(P[i, 0] - P[j, 0], P[i, 1] - P[j, 1])
            ov = r[i] + r[j] - d
            if ov > 0:
                E += ov * ov
        if P[i, 0] - r[i] < 0:
            E += (r[i] - P[i, 0]) ** 2
        if P[i, 0] + r[i] > 1:
            E += (P[i, 0] + r[i] - 1) ** 2
        if P[i, 1] - r[i] < 0:
            E += (r[i] - P[i, 1]) ** 2
        if P[i, 1] + r[i] > 1:
            E += (P[i, 1] + r[i] - 1) ** 2
    return E


def _sa(P0, r, n, rng, steps=30000):
    P = P0.copy()
    E = _energy(P, r, n)
    bestP = P.copy()
    bestE = E
    for s in range(steps):
        frac = s / steps
        sigma = 0.02 * (1 - frac) + 0.001 * frac
        T = 1e-4 * (1e-8 / 1e-4) ** frac
        i = rng.integers(n)
        old = P[i].copy()
        P[i, 0] += rng.normal(0, sigma)
        P[i, 1] += rng.normal(0, sigma)
        En = _energy(P, r, n)
        dE = En - E
        if dE <= 0 or rng.random() < np.exp(-dE / T):
            E = En
            if E < bestE:
                bestE = E
                bestP = P.copy()
        else:
            P[i] = old
    return bestP, bestE


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    rng = np.random.default_rng(987654321)

    if start is not None:
        S = np.asarray(start, dtype=float)
        if S.shape == (n, 3):
            P = S[:, :2].copy()
            r = S[:, 2].copy()
        else:
            P = rng.uniform(0.1, 0.9, (n, 2))
            r = np.full(n, 0.01)
    else:
        pts = []
        k = 5
        for j in range(k):
            for i in range(k):
                pts.append(((i + 0.5) / k, (j + 0.5) / k))
        pts = pts[:25]
        pts.append((0.5, 0.5))
        P = np.array(pts, dtype=float)
        r = np.full(n, 0.001)

    P, r = _feasible_shrink(P, r, n)
    best_P, best_r = P.copy(), r.copy()
    best_score = r.sum()

    Pk, rk = _kkt_solve(P, r, n)
    Pk, rk = _feasible_shrink(Pk, rk, n)
    Pk2, rk2 = _slsqp_polish(Pk, rk, n)
    Pk2, rk2 = _feasible_shrink(Pk2, rk2, n)
    if rk2.sum() > best_score:
        best_P, best_r = Pk2.copy(), rk2.copy()
        best_score = rk2.sum()

    Pn, rn = _slsqp_polish(P, r, n)
    Pn, rn = _feasible_shrink(Pn, rn, n)
    if rn.sum() > best_score:
        best_P, best_r = Pn.copy(), rn.copy()
        best_score = rn.sum()

    deadline = budget_seconds * 0.92
    attempt = 0
    while time.process_time() - t0 < deadline:
        attempt += 1
        # SA with radii fixed at best_r
        Psa, Esa = _sa(best_P, best_r, n, rng, steps=30000)
        if time.process_time() - t0 > deadline:
            break
        # restore radii, shrink, SLSQP polish with free radii
        Pc = Psa.copy()
        rc = best_r.copy()
        Pc, rc = _feasible_shrink(Pc, rc, n)
        Pn, rn = _slsqp_polish(Pc, rc, n)
        Pn, rn = _feasible_shrink(Pn, rn, n)
        if rn.sum() > best_score:
            best_P, best_r = Pn.copy(), rn.copy()
            best_score = rn.sum()
        # also try SA from current best occasionally
        if attempt % 3 == 0:
            Pp = best_P + rng.normal(0, 0.005, best_P.shape)
            Pp = np.clip(Pp, 0.0, 1.0)
            rp = best_r.copy()
            Pp, rp = _feasible_shrink(Pp, rp, n)
            Pn, rn = _slsqp_polish(Pp, rp, n)
            Pn, rn = _feasible_shrink(Pn, rn, n)
            if rn.sum() > best_score:
                best_P, best_r = Pn.copy(), rn.copy()
                best_score = rn.sum()

    P, r = best_P, best_r
    P, r = _feasible_shrink(P, r, n, margin=1e-10)
    out = np.column_stack([P, r])
    return out

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _unpack(v, n):
    return v[:2 * n].reshape(n, 2), v[2 * n:]


def _constraints(v, n):
    c, r = _unpack(v, n)
    cons = []
    cons.append(c[:, 0] - r)
    cons.append(1.0 - c[:, 0] - r)
    cons.append(c[:, 1] - r)
    cons.append(1.0 - c[:, 1] - r)
    dx = c[:, None, 0] - c[None, :, 0]
    dy = c[:, None, 1] - c[None, :, 1]
    d = np.sqrt(dx * dx + dy * dy)
    rs = r[:, None] + r[None, :]
    iu = np.triu_indices(n, 1)
    cons.append((d - rs)[iu])
    return np.concatenate(cons)


def _repair(out):
    n = out.shape[0]
    out = out.copy()
    out[:, 2] = np.maximum(out[:, 2], 1e-6)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    for _ in range(200):
        c = out[:, :2]
        r = out[:, 2]
        dx = c[:, None, 0] - c[None, :, 0]
        dy = c[:, None, 1] - c[None, :, 1]
        d = np.sqrt(dx * dx + dy * dy)
        rs = r[:, None] + r[None, :]
        iu = np.triu_indices(n, 1)
        viol = (rs - d)[iu]
        if np.max(viol) <= 1e-12:
            break
        for idx in np.where(viol > 0)[0]:
            i, j = iu[0][idx], iu[1][idx]
            excess = (rs[i, j] - d[i, j]) * 0.5 + 1e-12
            out[i, 2] = max(out[i, 2] - excess, 1e-6)
            out[j, 2] = max(out[j, 2] - excess, 1e-6)
        out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
        out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    return out


def _slsqp_polish(v0, n, maxiter=1500):
    def obj(v):
        _, r = _unpack(v, n)
        return -np.sum(r)

    def jac(v):
        g = np.zeros_like(v)
        g[2 * n:] = -1.0
        return g

    def cons_fun(v):
        return _constraints(v, n)

    def cons_jac(v):
        c, r = _unpack(v, n)
        J = np.zeros((4 * n, 3 * n))
        for i in range(n):
            J[i, 2 * i] = 1.0
            J[i, 2 * n + i] = -1.0
            J[n + i, 2 * i] = -1.0
            J[n + i, 2 * n + i] = -1.0
            J[2 * n + i, 2 * i + 1] = 1.0
            J[2 * n + i, 2 * n + i] = -1.0
            J[3 * n + i, 2 * i + 1] = -1.0
            J[3 * n + i, 2 * n + i] = -1.0
        iu = np.triu_indices(n, 1)
        npair = len(iu[0])
        Jp = np.zeros((npair, 3 * n))
        dx = c[:, None, 0] - c[None, :, 0]
        dy = c[:, None, 1] - c[None, :, 1]
        d = np.sqrt(dx * dx + dy * dy) + 1e-15
        for k, (i, j) in enumerate(zip(iu[0], iu[1])):
            ux = dx[i, j] / d[i, j]
            uy = dy[i, j] / d[i, j]
            Jp[k, 2 * i] = ux
            Jp[k, 2 * i + 1] = uy
            Jp[k, 2 * j] = -ux
            Jp[k, 2 * j + 1] = -uy
            Jp[k, 2 * n + i] = -1.0
            Jp[k, 2 * n + j] = -1.0
        return np.vstack([J, Jp])

    cons = {'type': 'ineq', 'fun': cons_fun, 'jac': cons_jac}
    bounds = [(0, 1)] * (2 * n) + [(1e-6, 0.5)] * n
    try:
        res = minimize(obj, v0, jac=jac, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return res.x
    except Exception:
        return v0


def _lp_radii(centers):
    n = centers.shape[0]
    dx = centers[:, None, 0] - centers[None, :, 0]
    dy = centers[:, None, 1] - centers[None, :, 1]
    d = np.sqrt(dx * dx + dy * dy)
    iu = np.triu_indices(n, 1)
    A = []
    b = []
    for i, j in zip(iu[0], iu[1]):
        row = np.zeros(n)
        row[i] = 1.0
        row[j] = 1.0
        A.append(row)
        b.append(d[i, j])
    for i in range(n):
        row = np.zeros(n)
        row[i] = 1.0
        A.append(row)
        b.append(min(centers[i, 0], 1.0 - centers[i, 0],
                     centers[i, 1], 1.0 - centers[i, 1]))
    A = np.array(A)
    b = np.array(b)
    c = -np.ones(n)
    bounds = [(1e-6, 0.5)] * n
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
        if res.success:
            return res.x
    except Exception:
        pass
    return np.full(n, 0.05)


def _row_xs(cnt, r, gap_pos, gap):
    if cnt == 1:
        return [0.5]
    xs = [0.0]
    for k in range(cnt - 1):
        step = 2.0 * r + (gap if k == gap_pos else 0.0)
        xs.append(xs[-1] + step)
    span = xs[-1]
    shift = 0.5 - span / 2.0
    return [x + shift for x in xs]


def _alt_row_seed(pattern, rA, ratio, gap_spec=None):
    pts = []
    y = 0.0
    for k, cnt in enumerate(pattern):
        rk = rA if (k % 2 == 0) else rA * ratio
        y += rk
        if gap_spec is not None and k in gap_spec and cnt >= 2:
            gp, gm = gap_spec[k]
            gp = min(gp, cnt - 2)
            xs = _row_xs(cnt, rk, gp, gm * rk)
        else:
            if cnt == 1:
                xs = [0.5]
            else:
                xs = np.linspace(rk, 1.0 - rk, cnt)
        for x in xs:
            pts.append((x, y))
        y += rk
    return np.array(pts)


def _compositions(total, parts, lo, hi):
    if parts == 1:
        if lo <= total <= hi:
            yield (total,)
        return
    for first in range(lo, hi + 1):
        rem = total - first
        if rem < lo * (parts - 1) or rem > hi * (parts - 1):
            continue
        for rest in _compositions(rem, parts - 1, lo, hi):
            yield (first,) + rest


def _cluster_rows(centers, tol=0.06):
    n = centers.shape[0]
    order = np.argsort(centers[:, 1])
    rows = []
    cur = [order[0]]
    for k in order[1:]:
        if abs(centers[k, 1] - centers[cur[-1], 1]) <= tol:
            cur.append(k)
        else:
            rows.append(cur)
            cur = [k]
    rows.append(cur)
    for r in rows:
        r.sort(key=lambda i: centers[i, 0])
    return rows


def _try_swap(centers, rows, ri):
    if ri + 1 >= len(rows):
        return None
    A = rows[ri]
    B = rows[ri + 1]
    if len(A) != len(B):
        return None
    new = centers.copy()
    for a, b in zip(A, B):
        new[a, 0], new[b, 0] = centers[b, 0], centers[a, 0]
    return new


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    rng = np.random.default_rng(987654321)

    if start is not None and np.asarray(start).shape == (n, 3):
        base = _repair(np.asarray(start, dtype=float))
    else:
        counts = [4, 5, 4, 5, 4, 4]
        r = 1.0 / (2.0 + np.sqrt(3.0) * 5.0)
        pts = []
        for k, cnt in enumerate(counts):
            y = r + k * np.sqrt(3.0) * r
            for j in range(cnt):
                x = 0.5 - (cnt - 1) * r + 2.0 * r * j
                pts.append((x, y, r))
        base = _repair(np.array(pts[:n]))

    best_out = base.copy()
    best_score = np.sum(base[:, 2])

    def to_v(out):
        return np.concatenate([out[:, :2].ravel(), out[:, 2]])

    def try_candidate(cand):
        nonlocal best_out, best_score
        cand = _repair(cand)
        s = np.sum(cand[:, 2])
        if s > best_score:
            best_score = s
            best_out = cand.copy()
            return True
        return False

    v = _slsqp_polish(to_v(base), n)
    c, r = _unpack(v, n)
    try_candidate(np.column_stack([c, r]))

    deadline = budget_seconds * 0.92

    rA_vals = [0.085, 0.095, 0.105, 0.115]
    ratio_vals = [0.75, 0.85, 0.95, 1.0]
    gap_mults = [0.5, 1.0, 1.5]

    patterns = []
    for nrows in (5, 6, 7):
        for comp in _compositions(n, nrows, 3, 7):
            patterns.append(comp)

    def pat_score(pat):
        best = -1.0
        for rA in rA_vals:
            for ratio in ratio_vals:
                h = sum((rA if k % 2 == 0 else rA * ratio) for k in range(len(pat)))
                if 2 * h <= 1.0:
                    s = 0.0
                    for k, cnt in enumerate(pat):
                        rk = rA if (k % 2 == 0) else rA * ratio
                        if cnt * 2 * rk <= 1.0 + 1e-9:
                            s += cnt * rk
                    best = max(best, s)
        return best

    patterns.sort(key=pat_score, reverse=True)

    seeds = []

    # Phase 1: uniform rows
    for pat in patterns:
        if time.process_time() - t0 >= deadline * 0.3:
            break
        for rA in rA_vals:
            if time.process_time() - t0 >= deadline * 0.3:
                break
            for ratio in ratio_vals:
                if time.process_time() - t0 >= deadline * 0.3:
                    break
                centers = _alt_row_seed(pat, rA, ratio)
                if centers.shape[0] != n:
                    continue
                if np.any(centers < -1e-9) or np.any(centers > 1.0 + 1e-9):
                    continue
                radii = _lp_radii(centers)
                cand = _repair(np.column_stack([centers, radii]))
                v = _slsqp_polish(to_v(cand), n)
                c, r = _unpack(v, n)
                cand = _repair(np.column_stack([c, r]))
                if try_candidate(cand):
                    seeds.append(cand.copy())

    # Phase 2: single-gap rows (base behaviour, reduced)
    for pat in patterns:
        if time.process_time() - t0 >= deadline * 0.5:
            break
        for rA in rA_vals:
            if time.process_time() - t0 >= deadline * 0.5:
                break
            for ratio in ratio_vals:
                if time.process_time() - t0 >= deadline * 0.5:
                    break
                gap_rows = [k for k, cnt in enumerate(pat) if cnt >= 3]
                if not gap_rows:
                    continue
                combos = []
                for k in gap_rows:
                    cnt = pat[k]
                    for gp in range(cnt - 1):
                        for gm in gap_mults:
                            combos.append((k, gp, gm))
                rng.shuffle(combos)
                for (k, gp, gm) in combos[:8]:
                    if time.process_time() - t0 >= deadline * 0.5:
                        break
                    gap_spec = {k: (gp, gm)}
                    centers = _alt_row_seed(pat, rA, ratio, gap_spec)
                    if centers.shape[0] != n:
                        continue
                    if np.any(centers < -1e-9) or np.any(centers > 1.0 + 1e-9):
                        continue
                    radii = _lp_radii(centers)
                    cand = _repair(np.column_stack([centers, radii]))
                    v = _slsqp_polish(to_v(cand), n)
                    c, r = _unpack(v, n)
                    cand = _repair(np.column_stack([c, r]))
                    if try_candidate(cand):
                        seeds.append(cand.copy())

    # Phase 2c: DOUBLE-VACANCY enumeration (the experiment)
    # Either two distinct rows each with one gap, or one row with two gaps.
    for pat in patterns:
        if time.process_time() - t0 >= deadline * 0.85:
            break
        nrows = len(pat)
        gap_rows = [k for k, cnt in enumerate(pat) if cnt >= 3]
        if len(gap_rows) < 1:
            continue
        for rA in rA_vals:
            if time.process_time() - t0 >= deadline * 0.85:
                break
            for ratio in ratio_vals:
                if time.process_time() - t0 >= deadline * 0.85:
                    break
                combos = []
                # (a) two distinct rows, each one gap
                if len(gap_rows) >= 2:
                    for ai in range(len(gap_rows)):
                        for bi in range(ai + 1, len(gap_rows)):
                            ka, kb = gap_rows[ai], gap_rows[bi]
                            for gpa in range(pat[ka] - 1):
                                for gpb in range(pat[kb] - 1):
                                    for gma in gap_mults:
                                        for gmb in gap_mults:
                                            combos.append(
                                                ('two', {ka: (gpa, gma), kb: (gpb, gmb)}))
                # (b) one row with two gaps
                for k in gap_rows:
                    cnt = pat[k]
                    if cnt < 4:
                        continue
                    for gp1 in range(cnt - 1):
                        for gp2 in range(gp1 + 1, cnt - 1):
                            for gm1 in gap_mults:
                                for gm2 in gap_mults:
                                    combos.append(
                                        ('one', {k: (gp1, gm1, gp2, gm2)}))
                if not combos:
                    continue
                rng.shuffle(combos)
                for kind, spec in combos[:40]:
                    if time.process_time() - t0 >= deadline * 0.85:
                        break
                    if kind == 'two':
                        gap_spec = spec
                        centers = _alt_row_seed(pat, rA, ratio, gap_spec)
                    else:
                        # one row with two gaps: build manually
                        k = list(spec.keys())[0]
                        gp1, gm1, gp2, gm2 = spec[k]
                        pts = []
                        y = 0.0
                        for kk, cnt in enumerate(pat):
                            rk = rA if (kk % 2 == 0) else rA * ratio
                            y += rk
                            if kk == k and cnt >= 2:
                                xs = [0.0]
                                for j in range(cnt - 1):
                                    step = 2.0 * rk
                                    if j == gp1:
                                        step += gm1 * rk
                                    if j == gp2:
                                        step += gm2 * rk
                                    xs.append(xs[-1] + step)
                                span = xs[-1]
                                shift = 0.5 - span / 2.0
                                xs = [x + shift for x in xs]
                            else:
                                if cnt == 1:
                                    xs = [0.5]
                                else:
                                    xs = np.linspace(rk, 1.0 - rk, cnt)
                            for x in xs:
                                pts.append((x, y))
                            y += rk
                        centers = np.array(pts)
                    if centers.shape[0] != n:
                        continue
                    if np.any(centers < -1e-9) or np.any(centers > 1.0 + 1e-9):
                        continue
                    radii = _lp_radii(centers)
                    cand = _repair(np.column_stack([centers, radii]))
                    v = _slsqp_polish(to_v(cand), n)
                    c, r = _unpack(v, n)
                    cand = _repair(np.column_stack([c, r]))
                    if try_candidate(cand):
                        seeds.append(cand.copy())

    # Phase 2b: adjacent-row swap loop on the best candidate
    swap_deadline = deadline * 0.95
    improved = True
    swap_round = 0
    while improved and time.process_time() - t0 < swap_deadline:
        improved = False
        swap_round += 1
        cur = best_out.copy()
        rows = _cluster_rows(cur[:, :2])
        for ri in range(len(rows) - 1):
            if time.process_time() - t0 >= swap_deadline:
                break
            swapped = _try_swap(cur[:, :2], rows, ri)
            if swapped is None:
                continue
            radii = _lp_radii(swapped)
            cand = _repair(np.column_stack([swapped, radii]))
            v = _slsqp_polish(to_v(cand), n)
            c, r = _unpack(v, n)
            cand = _repair(np.column_stack([c, r]))
            if try_candidate(cand):
                improved = True
                seeds.append(cand.copy())
                break
        if swap_round > 30:
            break

    # Phase 3: restarts around best
    while time.process_time() - t0 < deadline:
        lo, hi = np.log(0.005), np.log(0.06)
        sigma = np.exp(rng.uniform(lo, hi))
        src = best_out if (rng.random() < 0.7 or not seeds) else seeds[rng.integers(len(seeds))]
        pert = src.copy()
        pert[:, 0] += rng.normal(0, sigma, n)
        pert[:, 1] += rng.normal(0, sigma, n)
        scale = rng.uniform(0.97, 1.0, n)
        pert[:, 2] *= scale
        pert = _repair(pert)
        if time.process_time() - t0 >= deadline:
            break
        v = _slsqp_polish(to_v(pert), n)
        c, r = _unpack(v, n)
        try_candidate(np.column_stack([c, r]))

    out = best_out.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    return out

import numpy as np
import time
from scipy.optimize import minimize, linprog, NonlinearConstraint


def _unpack(v, n):
    return v[:2 * n].reshape(n, 2), v[2 * n:]


def _constraints(v, n):
    c, r = _unpack(v, n)
    cons = []
    cons.append(c[:, 0] - r)
    cons.append(1.0 - c[:, 0] - r)
    cons.append(c[:, 1] - r)
    cons.append(1.0 - c[:, 1] - r)
    dx = c[:, None, 0] - c[None, :, 0]
    dy = c[:, None, 1] - c[None, :, 1]
    d = np.sqrt(dx * dx + dy * dy)
    rs = r[:, None] + r[None, :]
    iu = np.triu_indices(n, 1)
    cons.append((d - rs)[iu])
    return np.concatenate(cons)


def _cons_jac(v, n):
    c, r = _unpack(v, n)
    J = np.zeros((4 * n, 3 * n))
    for i in range(n):
        J[i, 2 * i] = 1.0
        J[i, 2 * n + i] = -1.0
        J[n + i, 2 * i] = -1.0
        J[n + i, 2 * n + i] = -1.0
        J[2 * n + i, 2 * i + 1] = 1.0
        J[2 * n + i, 2 * n + i] = -1.0
        J[3 * n + i, 2 * i + 1] = -1.0
        J[3 * n + i, 2 * n + i] = -1.0
    iu = np.triu_indices(n, 1)
    npair = len(iu[0])
    Jp = np.zeros((npair, 3 * n))
    dx = c[:, None, 0] - c[None, :, 0]
    dy = c[:, None, 1] - c[None, :, 1]
    d = np.sqrt(dx * dx + dy * dy) + 1e-15
    for k, (i, j) in enumerate(zip(iu[0], iu[1])):
        ux = dx[i, j] / d[i, j]
        uy = dy[i, j] / d[i, j]
        Jp[k, 2 * i] = ux
        Jp[k, 2 * i + 1] = uy
        Jp[k, 2 * j] = -ux
        Jp[k, 2 * j + 1] = -uy
        Jp[k, 2 * n + i] = -1.0
        Jp[k, 2 * n + j] = -1.0
    return np.vstack([J, Jp])


def _repair(out):
    n = out.shape[0]
    out = out.copy()
    out[:, 2] = np.maximum(out[:, 2], 1e-6)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    for _ in range(200):
        c = out[:, :2]
        r = out[:, 2]
        dx = c[:, None, 0] - c[None, :, 0]
        dy = c[:, None, 1] - c[None, :, 1]
        d = np.sqrt(dx * dx + dy * dy)
        rs = r[:, None] + r[None, :]
        iu = np.triu_indices(n, 1)
        viol = (rs - d)[iu]
        if np.max(viol) <= 1e-12:
            break
        for idx in np.where(viol > 0)[0]:
            i, j = iu[0][idx], iu[1][idx]
            excess = (rs[i, j] - d[i, j]) * 0.5 + 1e-12
            out[i, 2] = max(out[i, 2] - excess, 1e-6)
            out[j, 2] = max(out[j, 2] - excess, 1e-6)
        out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
        out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    return out


def _slsqp_polish(v0, n, maxiter=1500):
    def obj(v):
        _, r = _unpack(v, n)
        return -np.sum(r)

    def jac(v):
        g = np.zeros_like(v)
        g[2 * n:] = -1.0
        return g

    def cons_fun(v):
        return _constraints(v, n)

    def cons_jac(v):
        return _cons_jac(v, n)

    cons = {'type': 'ineq', 'fun': cons_fun, 'jac': cons_jac}
    bounds = [(0, 1)] * (2 * n) + [(1e-6, 0.5)] * n
    try:
        res = minimize(obj, v0, jac=jac, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return res.x
    except Exception:
        return v0


def _trust_constr_polish(v0, n, maxiter=3000):
    def obj(v):
        _, r = _unpack(v, n)
        return -np.sum(r)

    def jac(v):
        g = np.zeros_like(v)
        g[2 * n:] = -1.0
        return g

    def cons_fun(v):
        return _constraints(v, n)

    def cons_jac(v):
        return _cons_jac(v, n)

    try:
        nlc = NonlinearConstraint(cons_fun, 0.0, np.inf, jac=cons_jac)
        bounds = [(0, 1)] * (2 * n) + [(1e-6, 0.5)] * n
        res = minimize(obj, v0, jac=jac, method='trust-constr',
                       bounds=bounds, constraints=[nlc],
                       options={'maxiter': maxiter, 'xtol': 1e-15,
                                'gtol': 1e-15, 'barrier_tol': 1e-15})
        return res.x
    except Exception:
        return v0


def _lp_radii(centers):
    n = centers.shape[0]
    dx = centers[:, None, 0] - centers[None, :, 0]
    dy = centers[:, None, 1] - centers[None, :, 1]
    d = np.sqrt(dx * dx + dy * dy)
    iu = np.triu_indices(n, 1)
    A = []
    b = []
    for i, j in zip(iu[0], iu[1]):
        row = np.zeros(n)
        row[i] = 1.0
        row[j] = 1.0
        A.append(row)
        b.append(d[i, j])
    for i in range(n):
        row = np.zeros(n)
        row[i] = 1.0
        A.append(row)
        b.append(min(centers[i, 0], 1.0 - centers[i, 0],
                     centers[i, 1], 1.0 - centers[i, 1]))
    A = np.array(A)
    b = np.array(b)
    c = -np.ones(n)
    bounds = [(1e-6, 0.5)] * n
    try:
        res = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
        if res.success:
            return res.x
    except Exception:
        pass
    return np.full(n, 0.05)


def _row_xs(cnt, r, gap_pos, gap):
    if cnt == 1:
        return [0.5]
    xs = [0.0]
    for k in range(cnt - 1):
        step = 2.0 * r + (gap if k == gap_pos else 0.0)
        xs.append(xs[-1] + step)
    span = xs[-1]
    shift = 0.5 - span / 2.0
    return [x + shift for x in xs]


def _alt_row_seed(pattern, rA, ratio, gap_spec=None):
    pts = []
    y = 0.0
    for k, cnt in enumerate(pattern):
        rk = rA if (k % 2 == 0) else rA * ratio
        y += rk
        if gap_spec is not None and k in gap_spec and cnt >= 2:
            gp, gm = gap_spec[k]
            gp = min(gp, cnt - 2)
            xs = _row_xs(cnt, rk, gp, gm * rk)
        else:
            if cnt == 1:
                xs = [0.5]
            else:
                xs = np.linspace(rk, 1.0 - rk, cnt)
        for x in xs:
            pts.append((x, y))
        y += rk
    return np.array(pts)


def _compositions(total, parts, lo, hi):
    if parts == 1:
        if lo <= total <= hi:
            yield (total,)
        return
    for first in range(lo, hi + 1):
        rem = total - first
        if rem < lo * (parts - 1) or rem > hi * (parts - 1):
            continue
        for rest in _compositions(rem, parts - 1, lo, hi):
            yield (first,) + rest


def _cluster_rows(centers, tol=0.06):
    n = centers.shape[0]
    order = np.argsort(centers[:, 1])
    rows = []
    cur = [order[0]]
    for k in order[1:]:
        if abs(centers[k, 1] - centers[cur[-1], 1]) <= tol:
            cur.append(k)
        else:
            rows.append(cur)
            cur = [k]
    rows.append(cur)
    for r in rows:
        r.sort(key=lambda i: centers[i, 0])
    return rows


def _try_swap(centers, rows, ri):
    if ri + 1 >= len(rows):
        return None
    A = rows[ri]
    B = rows[ri + 1]
    if len(A) != len(B):
        return None
    new = centers.copy()
    for a, b in zip(A, B):
        new[a, 0], new[b, 0] = centers[b, 0], centers[a, 0]
    return new


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 26
    rng = np.random.default_rng(987654321)

    if start is not None and np.asarray(start).shape == (n, 3):
        base = _repair(np.asarray(start, dtype=float))
    else:
        counts = [4, 5, 4, 5, 4, 4]
        r = 1.0 / (2.0 + np.sqrt(3.0) * 5.0)
        pts = []
        for k, cnt in enumerate(counts):
            y = r + k * np.sqrt(3.0) * r
            for j in range(cnt):
                x = 0.5 - (cnt - 1) * r + 2.0 * r * j
                pts.append((x, y, r))
        base = _repair(np.array(pts[:n]))

    best_out = base.copy()
    best_score = np.sum(base[:, 2])

    def to_v(out):
        return np.concatenate([out[:, :2].ravel(), out[:, 2]])

    def try_candidate(cand):
        nonlocal best_out, best_score
        cand = _repair(cand)
        s = np.sum(cand[:, 2])
        if s > best_score:
            best_score = s
            best_out = cand.copy()
            return True
        return False

    # SLSQP polish from base
    v = _slsqp_polish(to_v(base), n)
    c, r = _unpack(v, n)
    try_candidate(np.column_stack([c, r]))

    # trust-constr polish from current best
    v = to_v(best_out)
    v = _trust_constr_polish(v, n)
    c, r = _unpack(v, n)
    try_candidate(np.column_stack([c, r]))

    deadline = budget_seconds * 0.92

    rA_vals = [0.085, 0.095, 0.105, 0.115]
    ratio_vals = [0.75, 0.85, 0.95, 1.0]
    gap_mults = [0.5, 1.0, 1.5]

    patterns = []
    for nrows in (5, 6, 7):
        for comp in _compositions(n, nrows, 3, 7):
            patterns.append(comp)

    def pat_score(pat):
        best = -1.0
        for rA in rA_vals:
            for ratio in ratio_vals:
                h = sum((rA if k % 2 == 0 else rA * ratio) for k in range(len(pat)))
                if 2 * h <= 1.0:
                    s = 0.0
                    for k, cnt in enumerate(pat):
                        rk = rA if (k % 2 == 0) else rA * ratio
                        if cnt * 2 * rk <= 1.0 + 1e-9:
                            s += cnt * rk
                    best = max(best, s)
        return best

    patterns.sort(key=pat_score, reverse=True)

    seeds = []

    for pat in patterns:
        if time.process_time() - t0 >= deadline * 0.4:
            break
        for rA in rA_vals:
            if time.process_time() - t0 >= deadline * 0.4:
                break
            for ratio in ratio_vals:
                if time.process_time() - t0 >= deadline * 0.4:
                    break
                centers = _alt_row_seed(pat, rA, ratio)
                if centers.shape[0] != n:
                    continue
                if np.any(centers < -1e-9) or np.any(centers > 1.0 + 1e-9):
                    continue
                radii = _lp_radii(centers)
                cand = _repair(np.column_stack([centers, radii]))
                v = _slsqp_polish(to_v(cand), n)
                c, r = _unpack(v, n)
                cand = _repair(np.column_stack([c, r]))
                if try_candidate(cand):
                    seeds.append(cand.copy())

    for pat in patterns:
        if time.process_time() - t0 >= deadline * 0.85:
            break
        nrows = len(pat)
        for rA in rA_vals:
            if time.process_time() - t0 >= deadline * 0.85:
                break
            for ratio in ratio_vals:
                if time.process_time() - t0 >= deadline * 0.85:
                    break
                gap_rows = [k for k, cnt in enumerate(pat) if cnt >= 3]
                if not gap_rows:
                    continue
                combos = []
                for k in gap_rows:
                    cnt = pat[k]
                    for gp in range(cnt - 1):
                        for gm in gap_mults:
                            combos.append((k, gp, gm))
                rng.shuffle(combos)
                for (k, gp, gm) in combos[:12]:
                    if time.process_time() - t0 >= deadline * 0.85:
                        break
                    gap_spec = {k: (gp, gm)}
                    centers = _alt_row_seed(pat, rA, ratio, gap_spec)
                    if centers.shape[0] != n:
                        continue
                    if np.any(centers < -1e-9) or np.any(centers > 1.0 + 1e-9):
                        continue
                    radii = _lp_radii(centers)
                    cand = _repair(np.column_stack([centers, radii]))
                    v = _slsqp_polish(to_v(cand), n)
                    c, r = _unpack(v, n)
                    cand = _repair(np.column_stack([c, r]))
                    if try_candidate(cand):
                        seeds.append(cand.copy())

    swap_deadline = deadline * 0.95
    improved = True
    swap_round = 0
    while improved and time.process_time() - t0 < swap_deadline:
        improved = False
        swap_round += 1
        cur = best_out.copy()
        rows = _cluster_rows(cur[:, :2])
        for ri in range(len(rows) - 1):
            if time.process_time() - t0 >= swap_deadline:
                break
            swapped = _try_swap(cur[:, :2], rows, ri)
            if swapped is None:
                continue
            radii = _lp_radii(swapped)
            cand = _repair(np.column_stack([swapped, radii]))
            v = _slsqp_polish(to_v(cand), n)
            c, r = _unpack(v, n)
            cand = _repair(np.column_stack([c, r]))
            if try_candidate(cand):
                improved = True
                seeds.append(cand.copy())
                break
        if swap_round > 30:
            break

    while time.process_time() - t0 < deadline:
        lo, hi = np.log(0.005), np.log(0.06)
        sigma = np.exp(rng.uniform(lo, hi))
        src = best_out if (rng.random() < 0.7 or not seeds) else seeds[rng.integers(len(seeds))]
        pert = src.copy()
        pert[:, 0] += rng.normal(0, sigma, n)
        pert[:, 1] += rng.normal(0, sigma, n)
        scale = rng.uniform(0.97, 1.0, n)
        pert[:, 2] *= scale
        pert = _repair(pert)
        if time.process_time() - t0 >= deadline:
            break
        v = _slsqp_polish(to_v(pert), n)
        c, r = _unpack(v, n)
        try_candidate(np.column_stack([c, r]))

    out = best_out.copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-9, 1e-9)
    out[:, 0] = np.clip(out[:, 0], out[:, 2], 1.0 - out[:, 2])
    out[:, 1] = np.clip(out[:, 1], out[:, 2], 1.0 - out[:, 2])
    return out
